// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.sosimport android.app.Activityimport android.graphics.Colorimport android.os.Bundleimport android.view.Gravityimport android.view.WindowManagerimport android.widget.TextViewimport timber.log.Timber/** * NOUS — SOS Red-Screen Overlay Activity (Module 11 v3 — P1). * * Strategy §"EmergencySOSEngine": "Red screen: launch SosActivity (a * transparent Activity with red background + ZENITH TTS message)". * * A fullscreen, transparent-themed Activity with a red background and a * large white "SOS DISPATCHED" message. Launched by [EmergencySOSEngine.trigger] * the moment the countdown completes — gives the user immediate visual * confirmation that emergency services have been alerted. * * ## Lifecycle * *  - `onCreate`: configure window flags (keep screen on, show over lockscreen, *    turn screen on, dismiss keyguard). *  - `onResume`: schedule auto-dismiss after 5 seconds (so the user doesn't *    have to interact if they're incapacitated). *  - `onBackPressed`: ignored — must explicitly tap "Cancel" to dismiss. * * ## Permissions * *  - `SHOW_WHEN_LOCKED`, `TURN_SCREEN_ON` (Android 10+) — set via manifest *    `android:showOnLockScreen` + `android:turnScreenOn`. *  - `SYSTEM_ALERT_WINDOW` is NOT needed — we use a normal Activity, not *    an overlay. */class SosActivity : Activity() {    override fun onCreate(savedInstanceState: Bundle?) {        super.onCreate(savedInstanceState)        try {            // Configure window — show over lockscreen, turn screen on, keep on.            window?.apply {                addFlags(                    WindowManager.LayoutParams.FLAG_SHOW_WHEN_LOCKED or                        WindowManager.LayoutParams.FLAG_TURN_SCREEN_ON or                        WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON or                        WindowManager.LayoutParams.FLAG_DISMISS_KEYGUARD,                )                setBackgroundDrawableResource(android.R.color.holo_red_dark)            }        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "Failed to configure SosActivity window flags")        }        // Build a minimal UI programmatically — no layout XML needed.        val container = android.widget.FrameLayout(this).apply {            setBackgroundColor(Color.parseColor("#CC0000"))        }        val text = TextView(this).apply {            text = "SOS DISPATCHED\nEmergency services alerted.\nLocation sharing active."            setTextColor(Color.WHITE)            textSize = 24f            gravity = Gravity.CENTER            setPadding(48, 48, 48, 48)        }        val params = android.widget.FrameLayout.LayoutParams(            android.widget.FrameLayout.LayoutParams.MATCH_PARENT,            android.widget.FrameLayout.LayoutParams.WRAP_CONTENT,            Gravity.CENTER,        )        container.addView(text, params)        setContentView(container)    }    override fun onBackPressed() {        // Ignore back press — the user must explicitly wait for the        // auto-dismiss or use the system home button (which kills the        // SOS overlay but leaves the engine running).    }    private companion object {        private const val TAG = "SosActivity"    }}